894	// rejected as a whole. Field validation precedes the revision comparison, so a
895	// simultaneously wrong expectedRevision still reports invalid and Apply is
896	// never reached; neither the valid prefix nor any reset to unknown may leak
897	// through, the revision is not consumed and the rotation position survives.
898	func TestRegistryInvalidReplacementKeepsAcceptedStateAndCursor(t *testing.T) {
899		r := NewRegistry()
900		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
901		markHealth(t, r, "svc", "a", 1, 11, true, "")
902		markHealth(t, r, "svc", "b", 1, 22, true, "")
903		// One successful selection lands the cursor on a.
904		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 {
905			t.Fatalf("first select: %+v", out)
906		}
907	
908		// Valid prefix that would move a to a new address, invalid address later;
909		// expectedRevision 9 is also wrong but must not downgrade the answer to a
910		// conflict.
911		reg, err := r.ValidateRegistration("svc", 9, []Instance{
912			{ID: "a", Address: "h9:9"},
913			{ID: "b", Address: "bad-address"},
914		})
915		if err == nil {
916			t.Fatalf("expected an invalid-address error, got registration %+v", reg)
917		}
918		if msg := err.Error(); !strings.Contains(msg, `instance address "bad-address" is not a host:port address`) {
919			t.Fatalf("error should name the invalid address, got %q", msg)
920		}
921		if reg.Service != "" || reg.Revision != 0 || reg.Instances != nil {
922			t.Fatalf("failed validation must not return a partial registration: %+v", reg)
923		}
924	
925		// Nothing was applied: revision, original addresses, health and sequences
926		// are all the accepted ones; the rejected new address is absent.
927		assertAcceptedServiceState(t, r)
928	
929		// The cursor did not move: the rotation continues just after a and returns
930		// b's original address and accepted sequence instead of repeating a.
931		if out := selected(t, r, "svc", 1); out.InstanceID != "b" || out.Address != "h2:2" || out.Sequence != 22 || out.Revision != 1 {
932			t.Fatalf("select after invalid replacement should resume at b with its original state: %+v", out)
933		}
934		// Past the end the rotation wraps; the rejected new address must never be
935		// selectable even though it sat in the valid prefix.
936		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 {
937			t.Fatalf("wrapped select should use a's original address, got %+v", out)
938		}
939	}
940	
941	// TestRegistryConflictReplacementKeepsAcceptedStateAndCursor covers the
942	// conflict rejection condition: a fully valid replacement list that changes an
943	// existing address but carries an expectedRevision other than the current one
944	// is reported as conflict with both revisions and changes nothing — no revision
945	// bump, no address change, no health reset, no cursor movement.
946	func TestRegistryConflictReplacementKeepsAcceptedStateAndCursor(t *testing.T) {
947		r := NewRegistry()
948		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
949		markHealth(t, r, "svc", "a", 1, 11, true, "")
950		markHealth(t, r, "svc", "b", 1, 22, true, "")
951		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 {
952			t.Fatalf("first select: %+v", out)
953		}
954	
955		// Entire list parses; only expectedRevision 5 mismatches the current 1.
956		reg, err := r.ValidateRegistration("svc", 5, []Instance{
957			{ID: "a", Address: "hx:8080"},
958			{ID: "b", Address: "h2:2"},
959		})
960		if err != nil {
961			t.Fatalf("content should be valid, got %v", err)
962		}
963		out := r.Apply(reg)
964		if out.OK || out.Kind != OutcomeConflict || out.Changed ||
965			out.Expected != 5 || out.Actual != 1 || out.Revision != 1 {
966			t.Fatalf("replacement should conflict without changing state: %+v", out)
967		}
968		if msg := out.Reason; !strings.Contains(msg, "revision 1, not 5") {
969			t.Fatalf("conflict reason should state both revisions, got %q", msg)
970		}
971	
972		// The valid-but-conflicting replacement left no trace: a is still at its
973		// original address, healthy at the accepted sequence 11.
974		assertAcceptedServiceState(t, r)
975	
976		// The completed selection's position is untouched: the next healthy target
977		// in rotation is b, then the wrap returns a's original address — never the
978		// rejected hx:8080 and never a repeated a.
979		if out := selected(t, r, "svc", 1); out.InstanceID != "b" || out.Address != "h2:2" || out.Sequence != 22 || out.Revision != 1 {
980			t.Fatalf("select after conflict should resume at b with its original state: %+v", out)
981		}
982		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 || out.Revision != 1 {
983			t.Fatalf("wrapped select should use a's original address, got %+v", out)
984		}
985	}
